<script setup lang="ts">
import GenerationTaskProgress from './GenerationTaskProgress.vue'
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {generationEvolutionApi as api} from '../services/generationEvolutionApi'
import {useModelAccess} from '../composables/useModelAccess'
import {ApiError} from '../services/apiClient'
import type {RuntimeGuide,ErrorHelp,Insight} from '../types/generationEvolution'
const props=defineProps<{sessionId:string;revisionId:string}>()
const ensureModel=useModelAccess(),guide=ref<RuntimeGuide|null>(null),help=ref<Insight<ErrorHelp>|null>(null),error=ref(''),diagnostic=ref(''),busy=ref(false),done=ref<number[]>([])
let alive=true,timer:ReturnType<typeof setTimeout>|undefined,key=''
onMounted(()=>{void load();void refreshHelp()});onBeforeUnmount(()=>{alive=false;clearTimeout(timer)})
const message=(e:unknown)=>e instanceof ApiError?e.message:'运行向导暂时不可用，请重试'
async function load(){try{const g=await api.runtime(props.sessionId,props.revisionId);if(alive)guide.value=g}catch(e){if(alive)error.value=message(e)}}
async function refreshHelp(attempt=0){clearTimeout(timer);try{const h=await api.latestErrorHelp(props.sessionId,props.revisionId);if(!alive)return;help.value=h;if(h?.status==='RUNNING'&&attempt<300)timer=setTimeout(()=>void refreshHelp(attempt+1),2000)}catch(e){if(alive)error.value=message(e)}}
async function explain(){if(busy.value||help.value?.status==='RUNNING'||!diagnostic.value.trim())return;busy.value=true;error.value='';try{if(!await ensureModel('解释项目运行报错'))return;if(!alive)return;if(!key)key=crypto.randomUUID();const h=await api.errorHelp(props.sessionId,props.revisionId,diagnostic.value.trim(),key);if(!alive)return;help.value=h;key='';diagnostic.value='';await refreshHelp()}catch(e){if(alive)error.value=message(e)}finally{if(alive)busy.value=false}}
</script>
<template><section class="runtime"><details><summary>一步步把项目运行起来</summary><p v-if="error" class="notice error" role="alert">{{error}}</p><template v-if="guide"><p>根据文件识别：{{guide.language}}</p><p>依据：{{guide.evidence.join('、')||'README与源码文件'}}</p><article v-for="(step,index) in guide.steps" :key="step.title"><label><input v-model="done" type="checkbox" :value="index"> {{step.title}}</label><p>{{step.instruction}}</p><pre v-for="command in step.commands" :key="command">{{command}}</pre></article><p v-for="note in guide.notes" :key="note">{{note}}</p></template><button v-else class="button secondary" @click="load">重新读取运行步骤</button></details>
 <details><summary>运行报错了，帮我看看</summary><p>先移除密码、Token和个人信息，再粘贴关键报错。服务端会再做常见凭据模式脱敏；AI只提供建议。</p><form @submit.prevent="explain"><label for="project-runtime-error">遇到的报错</label><textarea id="project-runtime-error" v-model="diagnostic" maxlength="8000" rows="4" placeholder="说明刚执行了哪一步，再粘贴对应报错" :disabled="busy||help?.status==='RUNNING'"></textarea><button class="button primary" :disabled="busy||help?.status==='RUNNING'||!diagnostic.trim()">{{help?.status==='RUNNING'?'AI 正在解释…':'解释这个报错 · 使用 API 额度'}}</button></form><GenerationTaskProgress v-if="help" :key="help.id" :session-id="sessionId" kind="ERROR_HELP" :reference-id="help.id" @cancelled="refreshHelp()" /><p v-if="help?.errorMessage" role="alert">{{help.errorMessage}}</p><template v-if="help?.content"><h4>这是什么意思</h4><p>{{help.content.explanation}}</p><h4>可能原因</h4><ul><li v-for="cause in help.content.possibleCauses" :key="cause">{{cause}}</li></ul><h4>接下来怎么检查</h4><ol><li v-for="step in help.content.steps" :key="step.title"><b>{{step.title}}</b><p>{{step.instruction}}</p><pre v-if="step.command">{{step.command}}</pre></li></ol><p v-for="limit in help.content.limits" :key="limit">{{limit}}</p></template></details></section></template>
<style scoped>.runtime{margin-top:24px;border-top:1px solid var(--line);padding-top:14px}details{background:var(--surface-soft);padding:16px;margin:12px 0;border-radius:12px}summary{cursor:pointer;font-weight:650;font-size:16px}p,li{font-size:13px;line-height:1.8;color:var(--ink-soft)}article{padding:12px 0;border-bottom:1px solid var(--line)}label{font-size:14px;display:block;margin-top:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px;background:var(--code-bg);color:var(--code-ink);border-radius:8px;font-size:12px}textarea{width:100%;box-sizing:border-box;margin:10px 0}</style>
